		if !attributeType.Equal(attribute.Type(ctx)) {
			diags.AddError(
				"Invalid RollupValue Attribute Type",
				"While creating a RollupValue value, an invalid attribute value was detected. "+
					"A RollupValue must use a matching attribute type for the value. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("RollupValue Attribute Name (%s) Expected Type: %s\n", name, attributeType.String())+
					fmt.Sprintf("RollupValue Attribute Name (%s) Given Type: %s", name, attribute.Type(ctx)),
			)
		}
